import {useState} from 'react';
import {strategyName} from '../lib/strategyIdentity';
export type ManagedUser={user_id:string;username:string;is_admin:boolean;access_profile?:string;disabled?:boolean};
type Config={settings:Record<string,unknown>;revision:string;schema:{properties:Record<string,{title?:string;description?:string;enum?:string[]}>};credentials:Record<string,unknown>};
const tiers=[['watch','Watch'],['learning','Learning'],['learning_discord','Learning + Discord'],['trading','Trading'],['legacy','Existing full workspace']];
async function request(url:string,method='GET',body?:unknown){const r=await fetch(url,{method,credentials:'include',headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:'Check the entered values and try again.');return d;}
function label(key:string){const names:Record<string,string>={risk_pct:'Risk per trade (%)',risk_auto:'Use balance-based risk sizing',daily_loss_hard_cap_pct:'Daily loss hard cap (%)',max_position_dollars_pct:'Maximum position cost (% of balance)',max_concurrent_positions:'Maximum open positions',paper_trading:'Paper trading',broker_provider:'Broker',rr_ratio_mode:'Reward-to-risk mode',spread_gate_pct:'Maximum option spread (%)',vol_roc_threshold:'Volume change threshold',validated_strategy_ids:'Approved strategy IDs (read only)',simplified_exit_mode:'Exit engine (read only)',mtf_confirmation_enabled:'Multi-timeframe confirmation',orb_stage1_gain_pct:'Opening-range first profit target (%)',orb_stop_loss_pct:'Opening-range loss setting (%)'};if(names[key])return names[key];if(key.startsWith('enable_')){const id=key.slice(7).toUpperCase();const name=strategyName(id);if(name!==id)return name+' enabled';}return key.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());}
export function AdminUserControls({user,onSaved}:{user:ManagedUser;onSaved:()=>void}){
 const [edit,setEdit]=useState(false),[draft,setDraft]=useState({...user}),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);
 const [config,setConfig]=useState<Config|null>(null),[values,setValues]=useState<Record<string,unknown>>({}),[filter,setFilter]=useState('');
 const [keys,setKeys]=useState<Record<string,string>>({});
 const [jsonFields,setJsonFields]=useState<Record<string,string>>({});
 async function runAs(){if(!confirm(`Open CELO as ${user.username}? You will see their tier and their account. Saved changes affect them. This session lasts 30 minutes.`))return;setBusy(true);try{await request('/api/auth/run-as','POST',{user_id:user.user_id});localStorage.setItem('celo-account-switch', String(Date.now()));window.location.hash='/trading';window.location.reload();}catch(e){setMessage((e as Error).message);setBusy(false);}}
 async function account(revoke=false){if(!confirm(`Save access for ${draft.username}? ${revoke?'Their sessions will be signed out.':'Changed access signs out existing sessions.'} This does not stop their bot or close positions.`))return;setBusy(true);setMessage('');try{await request(`/api/admin/users/${user.user_id}`,'PATCH',{username:draft.username,is_admin:draft.is_admin,access_profile:draft.access_profile??'legacy',disabled:!!draft.disabled,revoke_sessions:revoke});setMessage('Access saved. Trading settings were not changed.');onSaved();}catch(e){setMessage((e as Error).message);}finally{setBusy(false);}}
 async function load(){setBusy(true);setMessage('');try{const d=await request(`/api/admin/users/${user.user_id}/configuration`);setConfig(d);setValues(d.settings);setJsonFields(Object.fromEntries(Object.entries(d.settings).filter(([,v])=>v!==null&&typeof v==='object').map(([k,v])=>[k,JSON.stringify(v,null,2)])));}catch(e){setMessage((e as Error).message);}finally{setBusy(false);}}
 async function saveKeys(){const credentials=Object.fromEntries(Object.entries(keys).filter(([,v])=>v.trim()));if(!Object.keys(credentials).length){setMessage('Enter the replacement key fields first. Blank fields stay unchanged.');return;}if(!confirm(`Replace the entered broker credentials for ${user.username} only? The bot must be stopped first. Do not change keys while this account has open positions.`))return;setBusy(true);try{await request(`/api/admin/users/${user.user_id}/credentials`,'POST',{confirm_user_id:user.user_id,credentials});setKeys({});setMessage('Selected broker credentials saved. A saved key is not proof that orders are ready.');}catch(e){setMessage((e as Error).message);}finally{setBusy(false);}}
 async function saveSettings(){if(!config)return;const next={...values};try{for(const [k,v] of Object.entries(jsonFields))next[k]=JSON.parse(v);}catch{setMessage('A list or advanced setting is not valid JSON. Correct it before saving.');return;}const changes=Object.fromEntries(Object.entries(next).filter(([k,v])=>JSON.stringify(v)!==JSON.stringify(config.settings[k])));if(!Object.keys(changes).length){setMessage('No settings changed.');return;}if(!confirm(`Apply these changes to ${user.username} only?\n${Object.keys(changes).map(k=>`${label(k)}: ${JSON.stringify(config.settings[k])} → ${JSON.stringify(changes[k])}`).join('\n')}\nThese settings may affect their trading. Existing execution checks still apply.`))return;setBusy(true);try{await request(`/api/admin/users/${user.user_id}/configuration`,'POST',{revision:config.revision,changes,confirm_user_id:user.user_id});await load();setMessage('Selected user’s settings saved.');}catch(e){setMessage((e as Error).message);}finally{setBusy(false);}}
 return <div className="admin-user-controls"><button className="btn btn-ghost" onClick={()=>setEdit(!edit)}>{edit?'Close controls':'Manage user'}</button>{!user.is_admin&&!user.disabled&&<button className="btn btn-ghost ml-2" disabled={busy} onClick={runAs}>Run as user</button>}<span className="text-xs ml-3">{tiers.find(t=>t[0]===(user.access_profile??'legacy'))?.[1]} · {user.disabled?'Sign-in disabled':'Sign-in allowed'}</span>
 {edit&&<section className="mt-4"><h4 className="font-semibold">Manage {user.username}</h4><p className="text-sm my-3">Access controls affect sign-in and visible tabs. They do not pause a running bot or close open positions. Learning + Discord records the tier; Discord delivery is not connected yet.</p><div className="admin-user-fields">
 <label>Username<input className="input" value={draft.username} onChange={e=>setDraft({...draft,username:e.target.value})}/></label>
 <label>Tier<select className="select" value={draft.access_profile??'legacy'} onChange={e=>setDraft({...draft,access_profile:e.target.value})}>{tiers.map(([v,t])=><option key={v} value={v}>{t}</option>)}</select></label>
 <label><input type="checkbox" checked={draft.is_admin} onChange={e=>setDraft({...draft,is_admin:e.target.checked})}/> Administrator access</label><label><input type="checkbox" checked={!!draft.disabled} onChange={e=>setDraft({...draft,disabled:e.target.checked})}/> Disable sign-in</label>
 </div><div className="flex flex-wrap gap-2 mt-3"><button className="btn btn-primary" disabled={busy} onClick={()=>account()}>Save access</button><button className="btn btn-ghost" disabled={busy} onClick={()=>account(true)}>Save and sign out sessions</button><button className="btn btn-ghost" disabled={busy} onClick={load}>Review account settings</button></div>
 {config&&<section className="mt-5"><h4 className="font-semibold">{user.username}’s configuration</h4><p className="text-sm my-2">Current broker and risk settings, strategy switches and saved preferences. Changes are reviewed before saving. Strategy approval rules still apply.</p><details className="my-3"><summary>Broker connections</summary><p className="text-sm">Stored secret keys are never shown. To replace keys, stop this user’s bot first and make sure no positions remain. Blank fields stay unchanged.</p>{Object.entries(config.credentials).filter(([k])=>k.startsWith('has_')).map(([k,v])=><p key={k}>{label(k.replace('has_',''))}: {v?'Saved':'Not saved'}</p>)}<div className="admin-user-fields">{['alpaca_api_key','alpaca_secret_key','tradier_api_key','tradier_account_id','tradier_market_api_key','tradier_live_account_id'].map(k=><label key={k}>{label(k)}<input className="input" type={k.includes('account')?'text':'password'} autoComplete="new-password" value={keys[k]??''} onChange={e=>setKeys({...keys,[k]:e.target.value})} placeholder="Leave blank to keep unchanged"/></label>)}</div><button className="btn btn-ghost mt-3" disabled={busy} onClick={saveKeys}>Replace entered credentials</button></details>
 <label>Find a setting<input className="input w-full my-3" value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Risk, broker, strategy..."/></label>
 <div className="admin-user-fields">{Object.entries(values).filter(([k])=>label(k).toLowerCase().includes(filter.toLowerCase())).map(([k,v])=><label key={k}><span>{label(k)}</span>{config.schema.properties[k]?.description&&<small>{config.schema.properties[k].description}</small>}{typeof v==='boolean'?<input type="checkbox" checked={v} disabled={k==='simplified_exit_mode'} onChange={e=>setValues({...values,[k]:e.target.checked})}/>:v!==null&&typeof v==='object'?<textarea className="input" rows={3} readOnly={k==='validated_strategy_ids'} value={jsonFields[k]??''} onChange={e=>setJsonFields({...jsonFields,[k]:e.target.value})}/>:<input className="input" type={typeof v==='number'?'number':'text'} step="any" value={v==null?'':String(v)} onChange={e=>setValues({...values,[k]:typeof v==='number'?Number(e.target.value):e.target.value})}/>}</label>)}</div>
 <button className="btn btn-primary mt-4" disabled={busy} onClick={saveSettings}>Review and save changes</button></section>}
 </section>}{message&&<p role="status" className="text-sm mt-3">{message}</p>}</div>
}
